<div class="d-flex justify-content-between mb-3"><h4>Roles &amp; Permissions</h4><?php if (Auth::can('admin.roles.create')): ?><a class="btn btn-primary" href="<?= url('roles/form') ?>"><i class="bi bi-plus-lg"></i> New role</a><?php endif; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0 align-middle"><thead class="table-light"><tr><th>Role</th><th>Description</th><th>Users</th><th>Permissions</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody>
<?php foreach ($roles as $r): ?><tr><td><b><?= e($r['name']) ?></b> <?= $r['is_super'] ? '<span class="badge text-bg-dark">Super</span>' : '' ?></td><td><?= e($r['description']) ?></td><td><?= (int)$r['users'] ?></td><td><?= $r['is_super'] ? 'All' : (int)$r['perms'] ?></td><td><?= badge($r['is_active'] ? 'active' : 'inactive') ?></td>
<td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-secondary" title="View permissions" href="<?= url('roles/view', ['id' => $r['id']]) ?>"><i class="bi bi-eye"></i></a>
<?php if (Auth::can('admin.roles.edit') && (!$r['is_super'] || Auth::isSuper())): ?><a class="btn btn-sm btn-outline-primary" href="<?= url('roles/form', ['id' => $r['id']]) ?>"><i class="bi bi-pencil"></i></a><?php endif; ?>
<?php if (Auth::can('admin.roles.delete') && !$r['is_super']): ?><form method="post" action="<?= url('roles/delete') ?>" class="d-inline" data-confirm="Delete / deactivate this role?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
